3	import { Badge, Box } from '@mantine/core';
4	import { useElementSize } from '@mantine/hooks';
5	import { CSSProperties, ReactNode } from 'react';
6	
7	/**
8	 * DebugSizeOverlay
9	 *
10	 * Wraps any container and shows a live badge with its current
11	 * width/height in both px and em (based on the root font-size),
12	 * so you can eyeball breakpoint behaviour while resizing.
13	 *
14	 * Usage:
15	 *   <DebugSizeOverlay>
16	 *     <YourLayout />
17	 *   </DebugSizeOverlay>
18	 *
19	 * Remove or wrap in `process.env.NODE_ENV === 'development'`
20	 * before shipping to production.
21	 */
22	
23	interface DebugSizeOverlayProps {
24	    children: ReactNode;
25	    /** root font-size in px used to convert to em, defaults to 16 */
26	    rootFontSize?: number;
27	    /** corner to pin the badge to */
28	    position?: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
29	    style?: CSSProperties;
30	}
31	
32	const positionStyles: Record<NonNullable<DebugSizeOverlayProps['position']>, CSSProperties> = {
33	    'top-left': { top: 4, left: 4 },
34	    'top-right': { top: 4, right: 4 },
35	    'bottom-left': { bottom: 4, left: 4 },
36	    'bottom-right': { bottom: 4, right: 4 },
37	};
38	
39	export function DebugSizeOverlay({
40	    children,
41	    rootFontSize = 16,
42	    position = 'top-right',
43	    style,
44	}: DebugSizeOverlayProps) {
45	    const { ref, width, height } = useElementSize();
46	
47	    const widthEm = (width / rootFontSize).toFixed(2);
48	    const heightEm = (height / rootFontSize).toFixed(2);
49	
50	    return (
51	        <Box ref={ref} pos="relative" style={{ ...style }}>
52	            <Badge
53	                variant="filled"
54	                color="dark"
55	                radius="sm"
56	                style={{
57	                    position: 'absolute',
58	                    zIndex: 9999,
59	                    pointerEvents: 'none',
60	                    fontFamily: 'monospace',
61	                    ...positionStyles[position],
62	                }}
63	            >
64	                {Math.round(width)}px × {Math.round(height)}px ({widthEm}em × {heightEm}em)
65	            </Badge>
66	            {children}
67	        </Box>
68	    );
69	}
